static const HanziDef* findHanzi(const char* utf8) {
  for (size_t i = 0; i < sizeof(HANZI_DATA) / sizeof(HANZI_DATA[0]); i++) {
    if (HANZI_DATA[i].bytes[0] == utf8[0] &&
        HANZI_DATA[i].bytes[1] == utf8[1] &&
        HANZI_DATA[i].bytes[2] == utf8[2]) {
      return &HANZI_DATA[i];
    }
  }
  return NULL;
}

static void drawHanzi(Adafruit_ST7789 *display, int x, int y, const HanziDef *ch, uint16_t color) {
  for (int row = 0; row < HANZI_H; row++) {
    uint16_t bits = ch->data[row];
    for (int col = 0; col < HANZI_W; col++) {
      if (bits & (0x8000 >> col)) {
        display->drawPixel(x + col, y + row, color);
      }
    }
  }
}

static int drawHanziText(Adafruit_ST7789 *display, int x, int y, const char *text, uint16_t color) {
  int cx = x;
  while (*text) {
    if ((*text & 0x80) && (*(text + 1) & 0x80)) {
      const HanziDef *ch = findHanzi(text);
      if (ch) {
        drawHanzi(display, cx, y, ch, color);
        cx += HANZI_CHAR_W;
        text += 3;
        continue;
      }
    }
    text++;
  }
  return cx;
}
